import type {NextConfig} from "next";

const nextConfig: NextConfig = {
    // The app is fully client-side (IndexedDB only, zero backend), so we ship a
    // static export that can be hosted anywhere and cached by the service worker.
    //
    // The offline worker is generated by `serwist build` (see
    // `serwist.config.ts` and the `build` script). We intentionally do not use
    // `withSerwistInit` here: Next 16 builds with Turbopack by default, which
    // `@serwist/next`'s webpack hook does not support. Serwist's configurator
    // mode is the Turbopack-compatible path and runs after the export.
    output: "export",
    // `next/image`'s default optimization server doesn't exist in a static
    // export; use unoptimized images instead.
    images: {
        unoptimized: true,
    },
    experimental: {
        // Keeps navigations/fetches pending while offline and retries once
        // connectivity returns, instead of throwing in the client.
        useOffline: true,
    },
  turbopack: {
    rules: {
      "*.css": {
        loaders: ["@tailwindcss/turbopack"],
        as: "*.css",
      },
    },
  },
};

export default nextConfig;
